COLL = ["populations", "cases", "maxims", "profiles", "elections", "lotteries", "problems", "games", "beliefs", "knowledge", "experiments", "thinkers", "arguments", "inferences", "bargains",
        "ruleCodes", "streams", "ubuntu", "poisson"]


def _id(v): return L._full(L.ID_RE, v)
def _arr(v): return v if isinstance(v, list) else []
def _fnum(v): return L.is_num(v)


def check_spec(spec):
    P, E, W = L.problems()
    m = spec.get("model") if isinstance(spec, dict) else None
    L.walk(m, T["MODEL"], "model", E, W)
    M = m if isinstance(m, dict) else {}
    def arr(k): return M[k] if isinstance(M.get(k), list) else []
    ids = {}
    for k in COLL:
        ids[k] = []
        for i, x in enumerate(arr(k)):
            if not isinstance(x, dict) or not isinstance(x.get("id"), str) or not _id(x["id"]): continue
            if x["id"] in ids[k]: E("duplicate", f"model.{k}[{i}].id", f"the id {x['id']} is used twice")
            else: ids[k].append(x["id"])
    for i, x in enumerate(arr("cases")):
        if isinstance(x, dict) and "preset" not in x and ("kAct" not in x or "kNot" not in x): E("value", f"model.cases[{i}]", "needs a preset, or kAct and kNot")
    for i, x in enumerate(arr("profiles")):
        if not isinstance(x, dict) or not isinstance(x.get("traits"), dict) or not (isinstance(x.get("scheme"), str) and x["scheme"] in T["VIRT"]): continue
        for k in x["traits"]:
            if k not in T["VIRT"][x["scheme"]]: E("value", f"model.profiles[{i}].traits.{k}", f"not a trait of {x['scheme']}")
    cands = {}
    for i, x in enumerate(arr("elections")):
        if not isinstance(x, dict): continue
        p, cs = f"model.elections[{i}]", []
        for j, c in enumerate(_arr(x.get("candidates"))):
            if not isinstance(c, str): continue
            if c in cs: E("duplicate", f"{p}.candidates[{j}]", f"the candidate {c} is listed twice")
            else: cs.append(c)
        if isinstance(x.get("id"), str): cands[x["id"]] = cs
        for j, b in enumerate(_arr(x.get("ballots"))):
            if not isinstance(b, dict): continue
            seen = []
            for k, c in enumerate(_arr(b.get("rank"))):
                if not isinstance(c, str) or not _id(c): continue
                if c not in cs: E("ref", f"{p}.ballots[{j}].rank[{k}]", f"no candidate {c}")
                elif c in seen: E("duplicate", f"{p}.ballots[{j}].rank[{k}]", f"the candidate {c} is ranked twice")
                else: seen.append(c)
        if isinstance(x.get("axis"), list):
            ax = x["axis"]
            if len(ax) != len(cs) or not all(c in ax for c in cs): E("value", f"{p}.axis", "needs every candidate once")
    for i, x in enumerate(arr("lotteries")):
        if not isinstance(x, dict) or not isinstance(x.get("outcomes"), list): continue
        p, os_ = f"model.lotteries[{i}]", x["outcomes"]
        ps = [o.get("p") if isinstance(o, dict) else None for o in os_]
        for j, v in enumerate(ps):
            if _fnum(v) and (v < 0 or v > 1): E("value", f"{p}.outcomes[{j}].p", "needs a probability from 0 to 1")
        if ps and all(_fnum(v) for v in ps) and abs(_jsum(ps) - 1) > 1e-9: E("value", f"{p}.outcomes", "the probabilities must sum to 1")
        for j, q in enumerate(_arr(x.get("priors"))):
            if isinstance(q, list) and len(q) != len(os_): E("size", f"{p}.priors[{j}]", "needs one probability per outcome")
    acts = {}
    for i, x in enumerate(arr("problems")):
        if not isinstance(x, dict): continue
        p = f"model.problems[{i}]"
        if "preset" in x:
            if isinstance(x["preset"], str) and x["preset"] in T["PROB"] and isinstance(x.get("id"), str): acts[x["id"]] = T["PROB"][x["preset"]]["acts"]
            continue
        if not all(isinstance(x.get(k), list) for k in ("acts", "states", "u", "pAct", "pCause")): E("value", p, "needs a preset, or acts, states, u, pAct and pCause"); continue
        if isinstance(x.get("id"), str): acts[x["id"]] = x["acts"]
        na, ns = len(x["acts"]), len(x["states"])
        for k in ("u", "pAct"):
            if len(x[k]) != na: E("size", f"{p}.{k}", "needs one row per act")
            for j, r in enumerate(x[k]):
                if isinstance(r, list) and len(r) != ns: E("size", f"{p}.{k}[{j}]", "needs one value per state")
        if len(x["pCause"]) != ns: E("size", f"{p}.pCause", "needs one value per state")
    for i, x in enumerate(arr("games")):
        if not isinstance(x, dict) or "preset" in x: continue
        p = f"model.games[{i}]"
        if not all(isinstance(x.get(k), list) for k in ("rows", "cols", "pay")): E("value", p, "needs a preset, or rows, cols and pay"); continue
        if len(x["pay"]) != len(x["rows"]) or any(not isinstance(r, list) or len(r) != len(x["cols"]) for r in x["pay"]):
            E("size", f"{p}.pay", "needs a pair of payoffs for every row and column")
    tour = M.get("tournament") if isinstance(M.get("tournament"), dict) else None
    if tour is not None:
        g = tour.get("game")
        if isinstance(g, str) and _id(g) and g not in ids["games"]: E("ref", "model.tournament.game", f"no game {g}")
        seen = []
        for j, s in enumerate(_arr(tour.get("strategies"))):
            if not isinstance(s, str): continue
            if s in seen: E("duplicate", f"model.tournament.strategies[{j}]", f"the strategy {s} is listed twice")
            else: seen.append(s)
    exp_pos = {}
    for i, x in enumerate(arr("experiments")):
        if not isinstance(x, dict): continue
        p = f"model.experiments[{i}]"
        te = T["TE"].get(x["te"]) if isinstance(x.get("te"), str) else None
        if te is None and "te" not in x and not (isinstance(x.get("options"), list) and isinstance(x.get("positions"), dict)):
            E("value", p, "needs te, or options and positions"); continue
        opts = x["options"] if isinstance(x.get("options"), list) else (te["o"] if te else [])
        if isinstance(x.get("positions"), dict):
            for k, v in x["positions"].items():
                if isinstance(v, str) and _id(v) and v not in opts: E("ref", f"{p}.positions.{k}", f"no option {v}")
        if isinstance(x.get("id"), str):
            exp_pos[x["id"]] = (list(te["p"].keys()) if te else []) + (list(x["positions"].keys()) if isinstance(x.get("positions"), dict) else [])
    thinker_ids = list(T["THINKERS"].keys()) + ids["thinkers"]
    for i, x in enumerate(arr("thinkers")):
        if not isinstance(x, dict): continue
        p = f"model.thinkers[{i}]"
        if not (isinstance(x.get("id"), str) and x["id"] in T["THINKERS"]) and ("born" not in x or "died" not in x or "trad" not in x):
            E("value", p, "needs born, died and trad (not a built-in thinker)")
        for j, r in enumerate(_arr(x.get("infl"))):
            if isinstance(r, str) and _id(r) and r not in thinker_ids: E("ref", f"{p}.infl[{j}]", f"no thinker {r}")

    for coll, sub, word in (("ruleCodes", "rules", "rule"), ("ubuntu", "options", "option")):
        for i, x in enumerate(arr(coll)):
            if not isinstance(x, dict): continue
            seen = []
            for j, r in enumerate(_arr(x.get(sub))):
                if not isinstance(r, dict) or not isinstance(r.get("id"), str): continue
                if r["id"] in seen: E("duplicate", f"model.{coll}[{i}].{sub}[{j}].id", f"the {word} {r['id']} is listed twice")
                else: seen.append(r["id"])

    pc = {}
    for i, x in enumerate(arr("poisson")):
        if not isinstance(x, dict): continue
        p, cs, seen = f"model.poisson[{i}]", [], []
        for j, c in enumerate(_arr(x.get("candidates"))):
            if not isinstance(c, str): continue
            if c in cs: E("duplicate", f"{p}.candidates[{j}]", f"the candidate {c} is listed twice")
            else: cs.append(c)
        if isinstance(x.get("id"), str): pc[x["id"]] = cs
        for j, t in enumerate(_arr(x.get("types"))):
            if not isinstance(t, dict): continue
            if isinstance(t.get("id"), str):
                if t["id"] in seen: E("duplicate", f"{p}.types[{j}].id", f"the type {t['id']} is listed twice")
                else: seen.append(t["id"])
            if isinstance(t.get("vote"), str) and _id(t["vote"]) and t["vote"] not in cs: E("ref", f"{p}.types[{j}].vote", f"no candidate {t['vote']}")
            if isinstance(t.get("u"), list) and len(t["u"]) != len(cs): E("value", f"{p}.types[{j}].u", "needs one utility per candidate")

    def out(o, at, E, W):
        k, of = o.get("kind"), o.get("of")
        tb = T["OUT"][k].get(of) if isinstance(k, str) and k in T["OUT"] and isinstance(of, str) else None
        if tb is None: E("output", at + ".of", f"{of} is not a {k} output of {ID}"); return
        L.walk(o, tb, at, E, W)
        for f, coll in T["REFS"].get(of, {}).items():
            vs = [(v, f"{at}.{f}[{j}]") for j, v in enumerate(o[f])] if isinstance(o.get(f), list) else [(o.get(f), f"{at}.{f}")]
            for v, pth in vs:
                if not (isinstance(v, str) and _id(v)): continue
                if coll == "cand":
                    cs = cands.get(o.get("election")) if isinstance(o.get("election"), str) else None
                    if cs is not None and v not in cs: E("ref", pth, f"no candidate {v}")
                elif coll == "pcand":
                    cs = pc.get(o.get("poisson")) if isinstance(o.get("poisson"), str) else None
                    if cs is not None and v not in cs: E("ref", pth, f"no candidate {v}")
                elif coll == "thinker":
                    if v not in thinker_ids: E("ref", pth, f"no thinker {v}")
                elif coll == "act":
                    a = acts.get(o.get("problem")) if isinstance(o.get("problem"), str) else None
                    if a is not None and v not in a: E("ref", pth, f"no act {v}")
                elif v not in ids[coll]: E("ref", pth, f"no {f} {v}")
        if of == "criterion" and o.get("criterion") == "iia" and "other" not in o: E("value", at, "iia needs other")
        if of == "teAnswer" and isinstance(o.get("position"), str) and isinstance(o.get("experiment"), str) and exp_pos.get(o["experiment"]) and o["position"] not in exp_pos[o["experiment"]]:
            E("ref", at + ".position", f"no position {o['position']}")
        if of in ("ipd", "match", "shares") and tour is None: E("value", at, "needs model.tournament")
        if of == "ipd" and tour is not None and isinstance(o.get("strategy"), str) and o["strategy"] not in _arr(tour.get("strategies")):
            E("ref", at + ".strategy", f"{o['strategy']} is not in model.tournament.strategies")
        if of in ("sorites", "degree", "bound") and not isinstance(M.get("sorites"), dict): E("value", at, "needs model.sorites")
        if of == "map" and not arr("thinkers"): E("value", at, "needs model.thinkers")
        if of == "trait" and isinstance(o.get("trait"), str):
            pr = next((x for x in arr("profiles") if isinstance(x, dict) and x.get("id") == o.get("profile")), None)
            if pr is not None and isinstance(pr.get("scheme"), str) and pr["scheme"] in T["VIRT"] and o["trait"] not in T["VIRT"][pr["scheme"]]:
                E("value", at + ".trait", f"not a trait of {pr['scheme']}")
    L.check_outputs(spec, ID, ["scalar", "series", "scene"], out, E, W)
    return P


def _jsum(a):
    s = 0
    for v in a: s += v
    return s


def _collect(v, kd, p, out):
    if isinstance(kd, str):
        if kd.rstrip("!") == "numx" and isinstance(v, str) and v.strip() != "": out.append((v, p, []))
        return
    if "$obj" in kd:
        if not isinstance(v, dict): return
        for k, sub in kd["$obj"].items():
            if k in v: _collect(v[k], sub, p + "." + k, out)
        return
    if "$map" in kd:
        if not isinstance(v, dict): return
        for k in v: _collect(v[k], kd["$map"], p + "." + k, out)
        return
    if "$list" in kd and isinstance(v, list):
        for i, x in enumerate(v): _collect(x, kd["$list"], f"{p}[{i}]", out)


def exprs(spec):
    out = []
    if not isinstance(spec, dict): return out
    _collect(spec.get("model"), {"$obj": T["MODEL"]}, "model", out)
    for i, o in enumerate(spec.get("outputs") if isinstance(spec.get("outputs"), list) else []):
        if isinstance(o, dict) and isinstance(o.get("kind"), str) and o["kind"] in T["OUT"] and isinstance(o.get("of"), str) and o["of"] in T["OUT"][o["kind"]]:
            _collect(o, {"$obj": T["OUT"][o["kind"]][o["of"]]}, f"outputs[{i}]", out)
    return out


def keys(spec):
    out = []
    if not isinstance(spec, dict) or not isinstance(spec.get("model"), dict): return out
    for i, x in enumerate(_arr(spec["model"].get("thinkers"))):
        if isinstance(x, dict) and isinstance(x.get("label"), str) and x["label"].strip() != "": out.append((x["label"], f"model.thinkers[{i}].label"))
    return out
